static inline const int16_t *PicoProWavetableTable(uint16_t table_index, uint8_t mip_index) {
  switch (mip_index) {
    case 0: return PICOPRO_WAVETABLES_MIP0[table_index];
    case 1: return PICOPRO_WAVETABLES_MIP1[table_index];
    case 2: return PICOPRO_WAVETABLES_MIP2[table_index];
    case 3: return PICOPRO_WAVETABLES_MIP3[table_index];
    case 4: return PICOPRO_WAVETABLES_MIP4[table_index];
    default: return PICOPRO_WAVETABLES_MIP0[table_index];
  }
}

static inline uint8_t PicoProWavetableMipIndexShift(uint8_t mip_index) {
  switch (mip_index) {
    case 0: return 23;
    case 1: return 24;
    case 2: return 25;
    case 3: return 26;
    case 4: return 27;
    default: return 23;
  }
}

static inline uint8_t PicoProWavetableMipFracShift(uint8_t mip_index) {
  switch (mip_index) {
    case 0: return 7;
    case 1: return 8;
    case 2: return 9;
    case 3: return 10;
    case 4: return 11;
    default: return 7;
  }
}

static inline uint16_t PicoProWavetableMipMask(uint8_t mip_index) {
  switch (mip_index) {
    case 0: return 511;
    case 1: return 255;
    case 2: return 127;
    case 3: return 63;
    case 4: return 31;
    default: return 511;
  }
}
